pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const dropZone=document.getElementById("drop-zone"),fileInput=document.getElementById("file-input"),loading=document.getElementById("loading"),result=document.getElementById("result"),summaryContent=document.getElementById("summary-content"),downloadBtn=document.getElementById("download-btn");async function processFile(e){if(e){dropZone.style.display="none",loading.style.display="block";try{const n=await e.arrayBuffer(),t=await pdfjsLib.getDocument(n).promise;let o=[];for(let e=1;e<=t.numPages;e++){const n=await t.getPage(e),i=(await n.getTextContent()).items.map(e=>e.str).join(" ");o.push(...i.split(/(?<=[.!?])\s+/))}generateSummary(o)}catch(e){alert("Error processing PDF."),location.reload()}}}function generateSummary(e){loading.style.display="none",result.style.display="block";const n=["summar","conclu","important","key","result","finding","essential","main","significan"];let t=e.filter(e=>{const t=e.toLowerCase();return e.length>50&&e.length<500&&n.some(e=>t.includes(e))}).slice(0,6);t.length<2&&(t=e.filter(e=>e.trim().length>100).slice(0,4));const o=t.map(e=>`• ${e.trim()}`).join("<br><br>");summaryContent.innerHTML=o,setTimeout(()=>{downloadSummary(t.join("\n\n"))},1500),downloadBtn.onclick=()=>downloadSummary(t.join("\n\n"))}function downloadSummary(e){const{jsPDF:n}=window.jspdf,t=new n;t.setFontSize(20),t.text("PDF Summary (generated by PDFIndi)",20,20),t.setFontSize(11);const o=t.splitTextToSize(e,170);t.text(o,20,35),t.save("pdfindi-summary.pdf")}dropZone.onclick=()=>fileInput.click(),fileInput.onchange=e=>processFile(e.target.files[0]);